import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>

static cublasHandle_t g_handle = nullptr;

static inline void check_cublas(cublasStatus_t st) {
    TORCH_CHECK(st == CUBLAS_STATUS_SUCCESS, "cuBLAS error: ", (int)st);
}

torch::Tensor gemm(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.is_cuda() && b.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(a.scalar_type() == torch::kFloat16 && b.scalar_type() == torch::kFloat16, "inputs must be fp16");
    TORCH_CHECK(a.dim() == 2 && b.dim() == 2, "inputs must be 2D");
    TORCH_CHECK(a.size(1) == b.size(0), "matmul shape mismatch");

    if (!a.is_contiguous()) a = a.contiguous();
    if (!b.is_contiguous()) b = b.contiguous();

    const int64_t M64 = a.size(0);
    const int64_t K64 = a.size(1);
    const int64_t N64 = b.size(1);
    auto c = torch::empty({M64, N64}, a.options());
    if (M64 == 0 || N64 == 0 || K64 == 0) return c;
    TORCH_CHECK(M64 <= INT_MAX && N64 <= INT_MAX && K64 <= INT_MAX, "matrix too large for cuBLAS int API");
    int M = (int)M64, N = (int)N64, K = (int)K64;

    if (g_handle == nullptr) {
        check_cublas(cublasCreate(&g_handle));
        check_cublas(cublasSetMathMode(g_handle, CUBLAS_TENSOR_OP_MATH));
    }
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    check_cublas(cublasSetStream(g_handle, stream));

    float alpha = 1.0f, beta = 0.0f;
    // Row-major C[M,N] = A[M,K] * B[K,N] is computed as column-major
    // C^T[N,M] = B^T[N,K] * A^T[K,M] without moving data.
    check_cublas(cublasGemmEx(
        g_handle,
        CUBLAS_OP_N, CUBLAS_OP_N,
        N, M, K,
        &alpha,
        (const void*)b.data_ptr<at::Half>(), CUDA_R_16F, N,
        (const void*)a.data_ptr<at::Half>(), CUDA_R_16F, K,
        &beta,
        (void*)c.data_ptr<at::Half>(), CUDA_R_16F, N,
        CUBLAS_COMPUTE_32F,
        CUBLAS_GEMM_DEFAULT_TENSOR_OP));
    return c;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gemm", &gemm, "fp16 gemm via cuBLAS");
}
'''

_ext = load_inline(
    name='h100_fp16_gemm_cublas_ext',
    cpp_sources=_src,
    functions=[],
    with_cuda=True,
    extra_cflags=['-O3'],
    extra_cuda_cflags=['-O3'],
    extra_ldflags=['-lcublas'],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
    def forward(self, a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
        return _ext.gemm(a, b)

